ox'=>'Inline flexbox','Inline grid'=>'Siatka wierszowa','Contents only'=>'Tylko zawartość','Hidden'=>'Ukryte','Basis'=>'Podstawa','Row reversed'=>'Odwrócony wiersz','Column'=>'Kolumna','Column reversed'=>'Odwrócona kolumna','Grow'=>'Rozwiń','Shrink'=>'Zmniejsz','Wrap'=>'Zawiń','No wrap'=>'Bez zawijania','Wrap reversed'=>'Zawijaj odwrócone','Font'=>'Czcionka','Italic'=>'Kursywa','Weight'=>'Waga','Thin (100)'=>'Cienki (100)','Extra light (200)'=>'Bardzo cienki (200)','Light (300)'=>'Lekki (300)','Regular (400)'=>'Regularny (400)','Medium (500)'=>'Średni (500)','Semi bold (600)'=>'Półpogrubiony (600)','Bold (700)'=>'Pogrubiona (700)','Extra bold (800)'=>'Ekstremalnie pogrubiona (800)','Black (900)'=>'Czarny (900)','Gap'=>'Odstęp','Area name'=>'Nazwa obszaru','Named areas'=>'Nazwane obszary','Offsets'=>'Przesunięcia','Justify content'=>'Wyrównaj zawartość','Space between'=>'Odstęp między','Space around'=>'Przestrzeń wokół','Space evenly'=>'Rozmieść równomiernie','Letter spacing'=>'Odstęp między literami','Line height'=>'Wysokość linii','Margin'=>'Margines','Max height'=>'Maksymalna wysokość','Max width'=>'Maksymalna szerokość','Min height'=>'Minimalna wysokość','Min width'=>'Minimalna szerokość','Overflow'=>'Przepełnienie','Visible'=>'Widoczny','Clip'=>'Przytnij','Scroll when needed'=>'Przewijaj w razie potrzeby','Always scroll'=>'Zawsze przewijaj','Padding'=>'Odstęp wewnętrzny','Place items'=>'Umieść elementy','Relative'=>'Względna','Absolute'=>'Absolutna','Fixed'=>'Naprawiono','Corner radius'=>'Promień zaokrąglenia narożników','Row span'=>'Rozpiętość wierszy','Justify'=>'Wyjustuj','Decoration'=>'Dekoracja','Overline'=>'Nadskrót','Strikethrough'=>'Przekreślenie','Text shadow'=>'Cień tekstu','Letter case'=>'Wielkość liter','Uppercase'=>'Wielkie litery','Lowercase'=>'Małe litery','Capitalise'=>'Kapitalizuj','Transition'=>'Przejście','Stack order (z-index)'=>'Kolejność warstw (z-index)','Add screen sizes of your own, such as a large desktop, a landscape tablet or a small 